from edge_sched import Scheduler, RollingStatsSnapshot, InputValidationError

# bool/0/float 拒绝
for bad in (True, False, 0, -1, 1.0):
    try:
        Scheduler(1, 1, latency_window_tasks=bad)
        print("FAIL accepted", bad)
    except InputValidationError:
        pass

s = Scheduler(workers=1, max_pending=2, latency_window_tasks=2)
s.submit("a", lambda: 1)
snap = s.rolling_snapshot()
assert isinstance(snap, RollingStatsSnapshot)
# 不可变/不可删
for attr in ("window_size", "sampled_finished", "queue_wait_ms"):
    for op in ("set", "del"):
        try:
            setattr(snap, attr, 9) if op == "set" else delattr(snap, attr)
            print("FAIL mutability", attr)
        except AttributeError:
            pass
try:
    snap.x = 1
    print("FAIL new attr")
except AttributeError:
    pass
# close 后可读且稳定
s.close()
d1, d2 = s.rolling_snapshot().to_dict(), s.rolling_snapshot().to_dict()
assert d1 == d2 and d1["window_size"] == 2 and d1["sampled_finished"] == 1
import json; json.dumps(d1)
print("immutability/close/JSON OK:", d1)
